PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?child ?childInLaw ?childInLawLabel WHERE {
  dbr:Spurius_Lucretius_Tricipitinus dbp:child ?child .
  { ?child dbp:spouse ?childInLaw }
  UNION
  { ?child dbo:spouse ?childInLaw }
  OPTIONAL { ?childInLaw rdfs:label ?childInLawLabel . FILTER (lang(?childInLawLabel) = "en") }
}
